local f=workspace.Installation2 local b=game.ServerStorage:FindFirstChild("AnciensScripts") or Instance.new("Folder",game.ServerStorage) b.Name="AnciensScripts" local o=workspace:FindFirstChild("InstallationCiseaux") if o then o.Parent=b end for n,p in {CiseauxServer=game.ServerScriptService,GrassServer=game.ServerScriptService,GrassClient=game.StarterPlayer.StarterPlayerScripts,GrassConfig=game.ReplicatedStorage} do local v=p:FindFirstChild(n) while v do pcall(function() v.Enabled=false end) v.Name=n.."_ANCIEN" v.Parent=b v=p:FindFirstChild(n) end f[n].Parent=p end f:Destroy() print("Installation OK !")
